--
-- Name: sp_buscarofertaaplicable(character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sp_buscarofertaaplicable(p_codigoproducto character varying, p_cantidad integer) RETURNS TABLE(id integer, nombreoferta character varying, tipooferta character varying, cantidadminima integer, preciooferta numeric, porcentajedescuento numeric, codigoproducto character varying, descripcionproducto character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        o.id,
        o.nombre AS nombreoferta,
        o.tipooferta,
        d.cantidadminima,
        d.preciooferta,
        d.porcentajedescuento,
        p.codigo AS codigoproducto,
        p.descripcion AS descripcionproducto
    FROM detalleofertasproductos d
    INNER JOIN ofertasproductos o ON d.idoferta = o.id
    INNER JOIN productos p ON d.idproducto = p.id
    WHERE p.codigo = p_codigoproducto
        AND o.activo = true -- Filtro booleano nativo de Postgres
        AND CURRENT_TIMESTAMP >= o.fechainicio
        AND (o.fechafin IS NULL OR CURRENT_TIMESTAMP <= o.fechafin)
        AND p_cantidad >= d.cantidadminima
    ORDER BY d.preciooferta ASC
    LIMIT 1; -- El equivalente al TOP 1 de SQL Server
END;
$$;


