--
-- Name: vw_ofertasconproductos; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_ofertasconproductos AS
 SELECT o.id AS id_oferta,
    o.nombre AS nombre_oferta,
    o.tipooferta,
    o.fechainicio,
    o.fechafin,
    o.activo AS oferta_activa,
    d.id AS id_detalle,
    d.cantidadminima,
    d.preciooferta,
    d.porcentajedescuento,
    p.id AS id_producto,
    p.codigo,
    p.descripcion,
    p.precio,
    p.costo
   FROM ((public.ofertasproductos o
     JOIN public.detalleofertasproductos d ON ((o.id = d.idoferta)))
     JOIN public.productos p ON ((d.idproducto = p.id)));


--
-- Name: vw_saldosproveedores; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_saldosproveedores AS
 SELECT proveedor,
    sum(debe) AS totaldebe,
    sum(haber) AS totalhaber,
    sum((debe - haber)) AS saldopendiente,
    count(*) AS cantidadmovimientos,
    max(fecha) AS ultimomovimiento
   FROM public.ctacteproveedores
  GROUP BY proveedor;


